import ajv8 from "ajv";
import { createRequire } from "node:module";
const req = createRequire(import.meta.url);
const ajv6 = req("./node_modules/eslint/node_modules/ajv");

function isObjectRecord(candidate) {
  return typeof candidate === "object" && candidate !== null;
}
function isAjvConstructor(candidate) {
  return typeof candidate === "function";
}
function supportsVocabularies(proto) {
  return isObjectRecord(proto) && "_addVocabularies" in proto;
}
function createSchemaCompiler(rawModule) {
  const unwrapped = isObjectRecord(rawModule) && "default" in rawModule ? rawModule.default : rawModule;
  if (!isAjvConstructor(unwrapped)) throw new Error("Unable to initialize Ajv validator");
  const options = supportsVocabularies(unwrapped.prototype)
    ? { strict: false, validateFormats: false, allErrors: true }
    : { format: false, unknownFormats: "ignore", jsonPointers: true, allErrors: true };
  return new unwrapped(options);
}

for (const [label, mod] of [["v8", ajv8], ["v8-wrapped", { default: ajv8 }], ["v6", ajv6], ["v6-wrapped", { default: ajv6 }]]) {
  const compiler = createSchemaCompiler(mod);
  // 1. Invalid schema throws
  let threw = false;
  try {
    compiler.compile({ type: "object", properties: { location: { type: "not-a-json-schema-type" } } });
  } catch {
    threw = true;
  }
  // 2. Missing required
  const vReq = compiler.compile({ type: "object", properties: { location: { type: "string" } }, required: ["location"] });
  const okReq = vReq({});
  // 3. Extra props + default + string number not coerced
  const vExtra = compiler.compile({
    type: "object",
    properties: {
      location: { type: "string" },
      units: { type: "string", enum: ["celsius", "fahrenheit"], default: "celsius" },
      zipCode: { type: "string" },
    },
    required: ["location"],
  });
  const inputExtra = { location: "Berlin", zipCode: "10115", traceId: "req-42" };
  const okExtra = vExtra(inputExtra);
  console.log(label, { threw, okReq, reqErrors: vReq.errors.length, okExtra, unchanged: JSON.stringify(inputExtra) });
}
'

